import time
import logging
from sdk.agent_base import AgentBase
from sdk.agent_config import AgentConfig


logger = logging.getLogger(__name__)


class ExampleAgent(AgentBase):
    """Example agent that processes simple tasks"""

    def execute_task(self, task):
        """Execute a task"""

        task_type = task.get("type", "unknown")
        task_data = task.get("data", {})

        logger.info(f"Processing task type: {task_type}")

        if task_type == "echo":
            # Simple echo task
            message = task_data.get("message", "")
            return {"echo": message}

        elif task_type == "compute":
            # Simple computation task
            operation = task_data.get("operation", "add")
            a = task_data.get("a", 0)
            b = task_data.get("b", 0)

            if operation == "add":
                result = a + b
            elif operation == "multiply":
                result = a * b
            elif operation == "subtract":
                result = a - b
            elif operation == "divide":
                result = a / b if b != 0 else None
            else:
                result = None

            return {"result": result}", "exit_code": 0, "error": null}
